// SQLite-only baseline for the FlexDB roadmap. Engine workloads match the
// native Flexscript worker; SQLite uses prepared statements and WAL/FULL.
#include <sqlite3.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/resource.h>
static sqlite3 *db;
static int n,distinct,width,nullp;
static char *pool;
struct rec {const char *ids;char name[80];int64_t ns,ops,sum,p50,p95,p99,clock;int state;};
static struct rec records[100];static int nr;
static void check(int ok){if(!ok){fprintf(stderr,"matrix SQLite: %s\n",db?sqlite3_errmsg(db):"closed");exit(1);}}
static int64_t now(void){struct timespec t;check(syscall(SYS_clock_gettime,CLOCK_MONOTONIC,&t)==0);return (int64_t)t.tv_sec*1000000000+t.tv_nsec;}
static void sql(const char *s){check(sqlite3_exec(db,s,0,0,0)==SQLITE_OK);}
static sqlite3_stmt *prepare(const char *s){sqlite3_stmt *p=0;check(sqlite3_prepare_v2(db,s,-1,&p,0)==SQLITE_OK);return p;}
static struct rec *record(const char *ids,const char *name,int64_t ns,int64_t ops,int64_t sum){check(nr<100);struct rec *r=&records[nr++];r->ids=ids;snprintf(r->name,sizeof r->name,"%s",name);r->ns=ns;r->ops=ops;r->sum=sum;return r;}
static char *text_key(int i){return pool+(size_t)(i%distinct)*(width+1);}
static void open_db(const char *path){check(sqlite3_open_v2(path,&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_NOMUTEX,0)==SQLITE_OK);sql("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA cache_size=-65536;");}
static void seeded(const char *path,int matches,int shared){pool=malloc((size_t)distinct*(width+1));check(pool!=0);char *hex="0123456789abcdef";for(int i=0;i<distinct;i++){char *p=text_key(i);for(int j=0;j<width;j++)p[j]=(char)('a'+j%26);int at=shared?width-8:0;for(int j=0;j<8;j++)p[at+j]=hex[(i>>((7-j)*4))&15];if(width>=32 && shared==2){p[16]=(char)195;p[17]=(char)164;}p[width]=0;}open_db(path);sql("CREATE TABLE items(id INTEGER PRIMARY KEY,key INTEGER NOT NULL,name TEXT NOT NULL,maybe INTEGER);");sqlite3_stmt *p=prepare("INSERT INTO items VALUES(?1,?2,?3,?4)");int64_t start=now();sql("BEGIN;");for(int i=0;i<n;i++){check(sqlite3_bind_int(p,1,i+1)==SQLITE_OK);check(sqlite3_bind_int(p,2,i%distinct)==SQLITE_OK);check(sqlite3_bind_text(p,3,text_key(i),width,SQLITE_STATIC)==SQLITE_OK);if(i%100<nullp)check(sqlite3_bind_null(p,4)==SQLITE_OK);else check(sqlite3_bind_int(p,4,i)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);if(i+1<n && (i+1)%(8388608/(width+32))==0)sql("COMMIT;BEGIN;");}sql("COMMIT;");record("W01,M02,M04","insert_reused",now()-start,n,(int64_t)matches*distinct*(distinct-1)/2);sqlite3_finalize(p);}
static int64_t count(sqlite3_stmt *p,int key,int text){if(text)check(sqlite3_bind_text(p,1,text_key(key),width,SQLITE_STATIC)==SQLITE_OK);else check(sqlite3_bind_int(p,1,key)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW);int64_t value=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);return value;}
static void learn(int text,int matches){sqlite3_stmt *p=prepare(text?"SELECT count(*) FROM items WHERE name=?1":"SELECT count(*) FROM items WHERE key=?1");int calls=(32768+n-1)/n;if(calls<4)calls=4;calls++;int64_t start=now(),sum=0;for(int i=0;i<calls-1;i++)sum+=count(p,i%distinct,text);sql(text?"CREATE INDEX items_name ON items(name);":"CREATE INDEX items_key ON items(key);");sum+=count(p,(calls-1)%distinct,text);struct rec *r=record("A01,A02,A05",text?"learn_text":"learn_integer",now()-start,calls,sum);r->state=2;check(sum==(int64_t)calls*matches);sqlite3_finalize(p);}
static void id_reads(const char *label,int mode){sqlite3_stmt *p=prepare("SELECT key FROM items WHERE id=?1");int64_t start=now(),sum=0;for(int i=0;i<100000;i++){int id=i%n+1;if(mode==1)id=(int)(((int64_t)i*7919)%n)+1;if(mode==2)id=i%32+1;if(mode==3)id=n+i+1;check(sqlite3_bind_int(p,1,id)==SQLITE_OK);int rc=sqlite3_step(p);if(mode==3){check(rc==SQLITE_DONE);}else{check(rc==SQLITE_ROW);sum+=sqlite3_column_int64(p,0)+1;check(sqlite3_step(p)==SQLITE_DONE);}check(sqlite3_reset(p)==SQLITE_OK);}record("Q01",label,now()-start,100000,sum);sqlite3_finalize(p);}
static void read_cases(int matches,int text){sql("BEGIN;");id_reads("id_sequential",0);id_reads("id_random",1);id_reads("id_hot32",2);id_reads("id_missing",3);int targets[]={0,1,n/100,n/10,n/2,n};sqlite3_stmt *p=prepare("SELECT count(*) FROM items WHERE key>=?1");for(int v=0;v<6;v++){int want=targets[v];int threshold=distinct-want/matches;int64_t start=now(),sum=0;for(int i=0;i<20;i++)sum+=count(p,threshold,0);int64_t elapsed=now()-start;check(sum==(int64_t)20*(want/matches)*matches);char label[80];snprintf(label,sizeof label,"scan_matches_%d",want/matches*matches);record("Q06",label,elapsed,20,sum);}sqlite3_finalize(p);p=prepare("SELECT count(*) FROM items WHERE key>=?1 AND maybe IS NOT NULL AND maybe%3=0");int64_t start=now(),sum=0;for(int i=0;i<20;i++)sum+=count(p,distinct/2,0);record("Q08","combined_scan",now()-start,20,sum);sqlite3_finalize(p);p=prepare("SELECT count(*) FROM items WHERE maybe IS NULL");start=now();sum=0;for(int i=0;i<20;i++){check(sqlite3_step(p)==SQLITE_ROW);sum+=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}record("Q05","null_scan",now()-start,20,sum);sqlite3_finalize(p);sql("COMMIT;");learn(text,matches);sql("BEGIN;");
 const char *kind=text?"text":"integer";char label[80];p=prepare(text?"SELECT count(*) FROM items WHERE name=?1":"SELECT count(*) FROM items WHERE key=?1");start=now();sum=0;for(int i=0;i<10000;i++)sum+=count(p,(int)(((int64_t)i*7919)%distinct),text);snprintf(label,sizeof label,"%s_hit",kind);record("Q02,Q03,Q04,A06",label,now()-start,10000,sum);check(sum==10000LL*matches);start=now();sum=0;for(int i=0;i<10000;i++){if(text)check(sqlite3_bind_text(p,1,"missing-key",-1,SQLITE_STATIC)==SQLITE_OK);else check(sqlite3_bind_int(p,1,n+i)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW);sum+=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}snprintf(label,sizeof label,"%s_miss",kind);record("Q02,Q03,Q04",label,now()-start,10000,sum);check(!sum);sqlite3_finalize(p);
 p=prepare(text?"SELECT id,key,name,maybe FROM items WHERE name=?1 ORDER BY id":"SELECT id,key,name,maybe FROM items WHERE key=?1 ORDER BY id");start=now();sum=0;for(int i=0;i<100;i++){int k=(int)(((int64_t)i*7919)%distinct);if(text)check(sqlite3_bind_text(p,1,text_key(k),width,SQLITE_STATIC)==SQLITE_OK);else check(sqlite3_bind_int(p,1,k)==SQLITE_OK);int rc,rows=0;int64_t prior=0;while((rc=sqlite3_step(p))==SQLITE_ROW){int64_t id=sqlite3_column_int64(p,0);check(id>prior);prior=id;sum+=id+sqlite3_column_int64(p,1)+strlen((const char*)sqlite3_column_text(p,2));if(sqlite3_column_type(p,3)!=SQLITE_NULL)sum+=sqlite3_column_int64(p,3);rows++;}check(rc==SQLITE_DONE && rows==matches);check(sqlite3_reset(p)==SQLITE_OK);}snprintf(label,sizeof label,"%s_materialized",kind);record("Q04,Q09",label,now()-start,100,sum);sqlite3_finalize(p);
 p=prepare("SELECT id FROM items WHERE key>=0 ORDER BY id LIMIT 25 OFFSET ?1");start=now();sum=0;for(int i=0;i<10;i++){check(sqlite3_bind_int(p,1,n/2)==SQLITE_OK);int rc;while((rc=sqlite3_step(p))==SQLITE_ROW)sum+=sqlite3_column_int64(p,0);check(rc==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}record("Q10","offset_page_middle",now()-start,10,sum);sqlite3_finalize(p);p=prepare("SELECT sum(key) FROM items");start=now();sum=0;for(int i=0;i<20;i++){check(sqlite3_step(p)==SQLITE_ROW);sum+=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}record("Q15","aggregate_sum_loop",now()-start,20,sum);sqlite3_finalize(p);sql("COMMIT;");}
static int cmp(const void *a,const void *b){int64_t x=*(const int64_t*)a,y=*(const int64_t*)b;return (x>y)-(x<y);}
static void latency(void){sql("BEGIN;");int64_t samples[2000],empty[2000],sum=0;for(int i=0;i<2000;i++){int64_t start=now(),end=now();empty[i]=end-start;}sqlite3_stmt *p=prepare("SELECT key FROM items WHERE id=?1");for(int i=0;i<2000;i++){int64_t start=now();check(sqlite3_bind_int(p,1,(int)(((int64_t)i*7919)%n)+1)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW);int64_t key=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);int64_t end=now();samples[i]=end-start;sum+=key;}sqlite3_finalize(p);qsort(samples,2000,sizeof(*samples),cmp);qsort(empty,2000,sizeof(*empty),cmp);struct rec *r=record("Q01","id_latency_sample",samples[1000],2000,sum);r->p50=samples[1000];r->p95=samples[1899];r->p99=samples[1979];r->clock=empty[1000];sql("COMMIT;");}
static void mutate(sqlite3_stmt *p,int id,int key,const char *name){check(sqlite3_bind_int(p,1,key)==SQLITE_OK);check(sqlite3_bind_text(p,2,name,-1,SQLITE_STATIC)==SQLITE_OK);check(sqlite3_bind_int(p,3,id-1)==SQLITE_OK);check(sqlite3_bind_int(p,4,id)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_changes(db)==1);check(sqlite3_reset(p)==SQLITE_OK);}
static int64_t lookup(int key){sqlite3_stmt *p=prepare("SELECT count(*) FROM items WHERE key=?1");int64_t value=count(p,key,0);sqlite3_finalize(p);return value;}
static void writes(void){learn(0,1);sqlite3_stmt *p=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4");int64_t start=now();sql("BEGIN;");for(int i=0;i<1000;i++)mutate(p,i+1,i,"same-key-new-text");sql("COMMIT;");record("W04","update_unindexed_field",now()-start,1000,1000);start=now();sql("BEGIN;");for(int i=0;i<1000;i++)mutate(p,i+1,n+i,"new-key");sql("COMMIT;");record("W04","update_indexed_field",now()-start,1000,1000);check(lookup(42)==0 && lookup(n+42)==1);start=now();sql("BEGIN;");for(int i=0;i<1000;i++)mutate(p,i+1,n*2+i,"rolled-back");sql("INSERT INTO items VALUES((SELECT max(id)+1 FROM items),-1,'rollback insert',NULL);DELETE FROM items WHERE id=1;ROLLBACK;");record("W08","rollback_mixed_1002",now()-start,1002,n);check(lookup(n)==1);char payload[257];memset(payload,'x',256);payload[256]=0;for(int pass=0;pass<2;pass++){start=now();sql("BEGIN;");for(int i=0;i<1000;i++)mutate(p,i+1,n+i,pass?"short":payload);sql("COMMIT;");record("W06",pass?"shrink_text_5":"grow_text_256",now()-start,1000,pass?5:256);}sqlite3_finalize(p);p=prepare("DELETE FROM items WHERE id=?1");start=now();sql("BEGIN;");for(int i=0;i<1000;i++){check(sqlite3_bind_int(p,1,i+1)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_changes(db)==1);check(sqlite3_reset(p)==SQLITE_OK);}sql("COMMIT;");record("W07","delete_batch",now()-start,1000,1000);sqlite3_finalize(p);p=prepare("SELECT key FROM items WHERE id=?1");start=now();int64_t sum=0;for(int i=0;i<10000;i++){check(sqlite3_bind_int(p,1,i%1000+1)==SQLITE_OK);int rc=sqlite3_step(p);sum+=(rc==SQLITE_ROW);check(rc==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}record("Q01,W07","deleted_id_reads",now()-start,10000,sum);check(!sum);sqlite3_finalize(p);start=now();for(int i=0;i<100;i++)sql("BEGIN;COMMIT;BEGIN;ROLLBACK;");record("W09","empty_transactions",now()-start,200,0);p=prepare("INSERT INTO items VALUES(?1,?2,'indexed insert',?3)");start=now();sql("BEGIN;");for(int i=0;i<1000;i++){check(sqlite3_bind_int(p,1,n+i+1)==SQLITE_OK);check(sqlite3_bind_int(p,2,n*3+i)==SQLITE_OK);check(sqlite3_bind_int(p,3,i)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}sql("COMMIT;");int64_t elapsed=now()-start;sqlite3_finalize(p);record("W03","indexed_insert_batch",elapsed,1000,lookup(n*3+42));check(lookup(n*3+42)==1);}
static void mixed(int writep){learn(0,1);sqlite3_stmt *p=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4");sqlite3_stmt *q=prepare("SELECT count(*) FROM items WHERE key=?1");int64_t start=now(),sum=0;int writes=0;for(int i=0;i<1000;i++){int key=(int)(((int64_t)i*7919)%n);if(i%100<writep){sql("BEGIN;");mutate(p,key+1,key,"mixed write");sql("COMMIT;");writes++;}else sum+=count(q,key,0);}char label[80];snprintf(label,sizeof label,"mixed_writes_%d",writep);record("X01,A03",label,now()-start,1000,sum);check(sum==1000-writes);sqlite3_finalize(p);sqlite3_finalize(q);}
static void lifecycle(const char *path){learn(0,1);int64_t start=now();check(sqlite3_close(db)==SQLITE_OK);db=0;record("S04","checkpoint_close",now()-start,n,n);start=now();open_db(path);sqlite3_stmt *p=prepare("SELECT key FROM items WHERE id=43");check(sqlite3_step(p)==SQLITE_ROW);int64_t key=sqlite3_column_int64(p,0);sqlite3_finalize(p);record("S01,S02,A07,D01","reopen_first_id",now()-start,1,key);check(key==42);p=prepare("SELECT count(*) FROM items NOT INDEXED WHERE key>=0");start=now();check(sqlite3_step(p)==SQLITE_ROW);int64_t count=sqlite3_column_int64(p,0);record("S03","first_full_scan",now()-start,1,count);check(count==n);check(sqlite3_reset(p)==SQLITE_OK);start=now();check(sqlite3_step(p)==SQLITE_ROW);count=sqlite3_column_int64(p,0);record("S03","cached_full_scan",now()-start,1,count);sqlite3_finalize(p);p=prepare("PRAGMA table_info(items)");start=now();for(int i=0;i<1000;i++){int fields=0,rc;while((rc=sqlite3_step(p))==SQLITE_ROW)fields++;check(rc==SQLITE_DONE && fields==4);check(sqlite3_reset(p)==SQLITE_OK);}record("D01","matching_schema_1000",now()-start,1000,0);sqlite3_finalize(p);p=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4");for(int pass=0;pass<2;pass++){start=now();sql("BEGIN;");for(int i=0;i<1000;i++)mutate(p,i+1,n*(pass+1)+i,"mapped update");sql("COMMIT;");record("A08,W04",pass?"mapped_later_write":"mapped_first_write",now()-start,1000,lookup(n*(pass+1)+42));}sqlite3_finalize(p);p=prepare("PRAGMA integrity_check");start=now();check(sqlite3_step(p)==SQLITE_ROW && !strcmp((const char*)sqlite3_column_text(p,0),"ok"));record("S08","integrity",now()-start,n,n);sqlite3_finalize(p);start=now();sql("VACUUM;");record("S07,S09","compaction",now()-start,n,n);check(sqlite3_close(db)==SQLITE_OK);db=0;}
static void joins(int matches){sqlite3_stmt *p=prepare("SELECT coalesce(a.maybe,0),coalesce(b.maybe,0) FROM items a JOIN items b ON a.key=b.key ORDER BY a.id,b.id");int64_t start=now(),sum=0;int rc,rows=0;while((rc=sqlite3_step(p))==SQLITE_ROW){sum+=sqlite3_column_int64(p,0)+sqlite3_column_int64(p,1)+1;rows++;}check(rc==SQLITE_DONE && rows==n*matches);record("Q11","self_join",now()-start,1,sum);sqlite3_finalize(p);}
static void schemas(void){sqlite3_stmt *p=prepare("PRAGMA table_info(items)");int64_t start=now();for(int i=0;i<1000;i++){int rc,fields=0;while((rc=sqlite3_step(p))==SQLITE_ROW)fields++;check(rc==SQLITE_DONE && fields==4);check(sqlite3_reset(p)==SQLITE_OK);}record("D01","schema_noop",now()-start,1000,0);sqlite3_finalize(p);start=now();sql("BEGIN;ALTER TABLE items ADD COLUMN note TEXT;COMMIT;");record("D02,D03,D04","schema_add_nullable",now()-start,n,n);start=now();sql("BEGIN;ALTER TABLE items ADD COLUMN flag INTEGER NOT NULL DEFAULT 7;COMMIT;");record("D02,D03,D04","schema_add_default",now()-start,n,n);start=now();sql("BEGIN;CREATE TABLE replacement(id INTEGER PRIMARY KEY,label TEXT NOT NULL,key INTEGER NOT NULL,maybe INTEGER,flag INTEGER NOT NULL);INSERT INTO replacement SELECT id,name,key,maybe,flag FROM items;DROP TABLE items;ALTER TABLE replacement RENAME TO items;COMMIT;");record("D02,D03,D04","schema_rename_reorder_drop",now()-start,n,n);start=now();sql("BEGIN;CREATE TABLE replacement(id INTEGER PRIMARY KEY,label TEXT NOT NULL,key TEXT NOT NULL,maybe INTEGER,flag INTEGER NOT NULL);INSERT INTO replacement SELECT id,label,CAST(key AS TEXT),maybe,flag FROM items;DROP TABLE items;ALTER TABLE replacement RENAME TO items;COMMIT;");record("D02,D03,D04","schema_convert",now()-start,n,n);p=prepare("SELECT key,flag FROM items WHERE id=43");check(sqlite3_step(p)==SQLITE_ROW && !strcmp((const char*)sqlite3_column_text(p,0),"42") && sqlite3_column_int(p,1)==7);sqlite3_finalize(p);}
static long long proc_number(const char *path,const char *key);
static void batching(void){int sizes[]={1,10,100,1000},next=n;sqlite3_stmt *p=prepare("INSERT INTO items VALUES(?1,?2,'batch insert',NULL)");for(int at=0;at<4;at++){int64_t start=now();for(int i=0;i<1000;){sql("BEGIN;");for(int j=0;j<sizes[at];j++,i++){check(sqlite3_bind_int(p,1,next+1)==SQLITE_OK);check(sqlite3_bind_int(p,2,next)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);next++;}sql("COMMIT;");}char label[80];snprintf(label,sizeof label,"insert_batch_%d",sizes[at]);record("W02,W05",label,now()-start,1000,next);}sqlite3_finalize(p);}
static void churn(void){learn(0,1);int *ids=malloc((size_t)n*sizeof(*ids));check(ids!=0);for(int i=0;i<n;i++)ids[i]=i+1;int next=n+1;sqlite3_stmt *u=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4"),*d=prepare("DELETE FROM items WHERE id=?1"),*ins=prepare("INSERT INTO items VALUES(?1,?2,'churn',?3)"),*get=prepare("SELECT key FROM items WHERE id=?1");int64_t total=now(),phase=total;for(int cycle=1;cycle<=100;cycle++){sql("BEGIN;");for(int i=0;i<n;i++)mutate(u,ids[i],cycle*n+i,"churn");for(int i=0;i<10;i++){check(sqlite3_bind_int(d,1,ids[i])==SQLITE_OK);check(sqlite3_step(d)==SQLITE_DONE);check(sqlite3_changes(db)==1);check(sqlite3_reset(d)==SQLITE_OK);check(sqlite3_bind_int(ins,1,next)==SQLITE_OK);check(sqlite3_bind_int(ins,2,cycle*n+i)==SQLITE_OK);check(sqlite3_bind_int(ins,3,ids[i]-1)==SQLITE_OK);check(sqlite3_step(ins)==SQLITE_DONE);check(sqlite3_reset(ins)==SQLITE_OK);ids[i]=next++;}sql("COMMIT;");if(cycle%25==0){int64_t elapsed=now()-phase,sum=0;for(int i=0;i<n;i++){check(sqlite3_bind_int(get,1,ids[i])==SQLITE_OK);check(sqlite3_step(get)==SQLITE_ROW);sum+=sqlite3_column_int64(get,0);check(sqlite3_reset(get)==SQLITE_OK);}check(sum==1LL*cycle*n*n+1LL*n*(n-1)/2);char label[80];snprintf(label,sizeof label,"churn_cycle_%d",cycle);struct rec *r=record("W10,M01",label,elapsed,25*(n+20),sum);r->clock=proc_number("/proc/self/status","VmRSS:");int64_t start=now();sql("VACUUM;");snprintf(label,sizeof label,"churn_compact_%d",cycle);record("W10,S07",label,now()-start,n,sum);phase=now();}}record("W10","churn_total",now()-total,100*(n+20),100LL*n*n+1LL*n*(n-1)/2);sqlite3_finalize(u);sqlite3_finalize(d);sqlite3_finalize(ins);sqlite3_finalize(get);free(ids);}
static void adaptive(void){int budgets[]={0,262144,1048576,4194304,8388608};for(int v=0;v<5;v++){sql("DROP INDEX IF EXISTS items_key;");char setting[80];snprintf(setting,sizeof setting,"PRAGMA cache_size=-%d;",budgets[v]?budgets[v]/1024:65536);sql(setting);sqlite3_stmt *p=prepare("SELECT count(*) FROM items WHERE key=?1");int64_t start=now(),sum=0;for(int i=0;i<200;i++){if(i==4 && budgets[v])sql("CREATE INDEX items_key ON items(key);");sum+=count(p,(int)(((int64_t)i*7919)%n),0);}int64_t elapsed=now()-start;char name[80];snprintf(name,sizeof name,"budget_%d",budgets[v]);struct rec *r=record("A01,A02,A04,A05",name,elapsed,200,sum);r->state=budgets[v]?2:0;check(sum==200);sqlite3_finalize(p);}sqlite3_stmt *p=prepare("SELECT count(*) FROM items WHERE name=?1");int64_t start=now(),sum=0;for(int i=0;i<2000;i++){if(i==4)sql("CREATE INDEX items_name ON items(name);");sum+=count(p,(int)(((int64_t)i*7919)%n),1);}record("A03,A10","switch_to_text",now()-start,2000,sum);check(sum==2000);sqlite3_finalize(p);p=prepare("SELECT count(*) FROM items WHERE key=?1");start=now();sum=0;for(int i=0;i<200;i++)sum+=count(p,(int)(((int64_t)i*7919)%n),0);record("A03,A10","return_to_integer",now()-start,200,sum);sqlite3_finalize(p);p=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4");sql("BEGIN;");for(int i=0;i<n*9/10;i++)mutate(p,i+1,0,text_key(i));sql("COMMIT;");sqlite3_finalize(p);p=prepare("SELECT count(*) FROM items WHERE key=?1");start=now();sum=0;for(int i=0;i<100;i++)sum+=count(p,0,0);record("A03,Q04","demand_becomes_broad",now()-start,100,sum);check(sum==100LL*(n*9/10));sqlite3_finalize(p);}
static void crash_seed(void){learn(0,1);sql("PRAGMA wal_checkpoint(TRUNCATE);");sqlite3_stmt *p=prepare("UPDATE items SET key=?1,name=?2,maybe=?3 WHERE id=?4");sql("BEGIN;");mutate(p,43,n+42,"committed tail");sql("COMMIT;BEGIN;");mutate(p,44,n+43,"uncommitted tail");sqlite3_finalize(p);}
static void recover(const char *path){int64_t start=now();open_db(path);sqlite3_stmt *p=prepare("SELECT key FROM items WHERE id=43 OR id=44 ORDER BY id");check(sqlite3_step(p)==SQLITE_ROW);int64_t a=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_ROW);int64_t b=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);sqlite3_finalize(p);record("R01,S06,A09","process_exit_recovery",now()-start,1,a+b);check(a==n+42 && b==43);p=prepare("SELECT count(*) FROM items WHERE key=?1");start=now();int64_t found=count(p,n+42,0);record("A09,A07","first_equality_after_tail",now()-start,1,found);check(found==1);sqlite3_finalize(p);}
static long long proc_number(const char *path,const char *key){FILE *f=fopen(path,"r");check(f!=0);char line[512];long long value=-1;while(fgets(line,sizeof line,f)){if(!strncmp(line,key,strlen(key))){check(sscanf(line+strlen(key),"%lld",&value)==1);break;}}fclose(f);check(value>=0);return value;}
int main(int argc,char **argv){if(argc!=8)return 1;n=atoi(argv[2]);int matches=atoi(argv[4]);width=atoi(argv[5]);int shared=atoi(argv[6]);nullp=atoi(argv[7]);if(n<1000 || n>100000 || matches<1 || n%matches || width<8 || width>256)return 1;distinct=n/matches;int64_t whole=now();const char *family=argv[3];if(!strcmp(family,"recover"))recover(argv[1]);else seeded(argv[1],matches,shared);if(!strcmp(family,"read") || !strcmp(family,"text")){read_cases(matches,!strcmp(family,"text"));latency();}else if(!strcmp(family,"write"))writes();else if(!strcmp(family,"lifecycle"))lifecycle(argv[1]);else if(!strcmp(family,"join"))joins(matches);else if(!strcmp(family,"schema"))schemas();else if(!strcmp(family,"adaptive"))adaptive();else if(!strcmp(family,"batch"))batching();else if(!strcmp(family,"churn"))churn();else if(!strcmp(family,"crash"))crash_seed();else if(!strcmp(family,"recover")){}else if(!strncmp(family,"mixed",5))mixed(atoi(family+5));else check(0);if(db && strcmp(family,"crash")){int64_t start=now();check(sqlite3_close(db)==SQLITE_OK);db=0;record("S04","final_close",now()-start,n,n);}record("S05","session_total",now()-whole,1,0);struct stat st;check(stat(argv[1],&st)==0);struct rusage usage;check(getrusage(RUSAGE_SELF,&usage)==0);printf("{\"cases\":[");for(int i=0;i<nr;i++){struct rec *r=&records[i];if(i)printf(",");printf("{\"ids\":\"%s\",\"case\":\"%s\",\"ns\":%lld,\"operations\":%lld,\"checksum\":%lld",r->ids,r->name,(long long)r->ns,(long long)r->ops,(long long)r->sum);if(r->state)printf(",\"index_state\":%d",r->state);if(!strncmp(r->name,"churn_cycle_",12))printf(",\"rss_kib\":%lld",(long long)r->clock);if(r->p50)printf(",\"p50_ns\":%lld,\"p95_ns\":%lld,\"p99_ns\":%lld,\"clock_pair_p50_ns\":%lld",(long long)r->p50,(long long)r->p95,(long long)r->p99,(long long)r->clock);printf("}");}printf("],\"bytes\":%lld,\"peak_kib\":%lld,\"minor_faults\":%ld,\"major_faults\":%ld,\"write_bytes\":%lld,\"read_bytes\":%lld}\n",(long long)st.st_size,proc_number("/proc/self/status","VmHWM:"),usage.ru_minflt,usage.ru_majflt,proc_number("/proc/self/io","write_bytes:"),proc_number("/proc/self/io","read_bytes:"));free(pool);return 0;}
